local paths={}local _BASE=""local _CCZ=""local function findBase()if shell then local prog=shell.getRunningProgram()local progDir=fs.getDir(prog)if progDir and progDir~=""and progDir~="."then local parent=fs.getDir(progDir)_CCZ=progDir.."/"_BASE=(parent~=""and parent~=".")and(parent.."/")or""return end end local candidates={"","/","disk/","disk2/"}for _,prefix in ipairs(candidates)do local try=prefix.."CCZombies/paths.lua"if fs.exists(try)then _BASE=prefix _CCZ=prefix.."CCZombies/"return end end if fs.find then local results=fs.find("CCZombies/paths.lua")if results and#results>0 then local p=results[1]local dir=fs.getDir(p)local parent=fs.getDir(dir)_CCZ=dir.."/"_BASE=(parent~=""and parent~=".")and(parent.."/")or""return end end _BASE=""_CCZ="CCZombies/"end findBase()paths.BASE=_BASE paths.CCZ=_CCZ function paths.asset(filename)return _CCZ..filename end function paths.character(filename)return _CCZ.."characters/"..filename end function paths.mod(modName,filename)if filename then return _CCZ.."mods/"..modName.."/"..filename end return _CCZ.."mods/"..modName.."/"end function paths.map(name)local base=name:gsub("%.ccz$","")local primary=_BASE.."maps/"..base..".ccz"local secondary=_CCZ.."maps/"..base..".ccz"if fs.exists(primary)then return primary end if fs.exists(secondary)then return secondary end return primary end function paths.mapsDir()local primary=_BASE.."maps/"if fs.exists(primary)then return primary end return _CCZ.."maps/"end local CHAR_SUFFIX={drnightheart="DrNightheart",arissnightheart="ArissNightheart",alicee="AliceE",bayard="Bayard",}function paths.gun(weaponId,charId)if charId then local suffix=CHAR_SUFFIX[charId]or charId for _,ext in ipairs({".nfp",".blit"})do local p=_BASE.."guns/"..weaponId.."_"..suffix..ext if fs.exists(p)then return p end end end for _,ext in ipairs({".nfp",".blit"})do local p=_BASE.."guns/"..weaponId..ext if fs.exists(p)then return p end end return _BASE.."guns/"..weaponId..".nfp"end function paths.audio(filename)local p=_BASE.."audio/"..filename if fs.exists(p)then return p end return _CCZ.."audio/"..filename end function paths.model(filename)local tries={filename,_BASE.."models/"..filename,_BASE.."maps/models/"..filename,_CCZ.."models/"..filename,}for _,p in ipairs(tries)do if fs.exists(p)then return p end end return tries[2]end function paths.settings()return _BASE.."ccz_settings.json"end function paths.scanMaps()local dir=paths.mapsDir()local out={}if not fs.exists(dir)then return out end for _,f in ipairs(fs.list(dir))do if f:match("%.ccz$")then out[#out+1]=f:sub(1,-5)end end table.sort(out)return out end return paths